/*
 * Tests for the generated service worker.
 *
 * The claim this guards is the one the whole feature rests on: that the site works with
 * no signal. `out/sw.js` is generated by `fontend/scripts/build_sw.mjs` from the real
 * export, so this test loads the generated file and runs it against a mocked Service
 * Worker environment rather than testing a copy of its logic.
 *
 * Run with: npm test (after npm run build, which is what writes out/sw.js)
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

const SW_PATH = join(process.cwd(), "out", "sw.js");

interface FakeResponse {
  ok: boolean;
  status: number;
  url: string;
  type: string;
  body: string;
  clone(): FakeResponse;
}

/**
 * A Cache that behaves like the real one for the operations the worker uses: `add`
 * fetches and stores, `put` stores a response, `match` returns what was stored.
 */
class FakeCache {
  private store = new Map<string, string>();

  async add(request: { url: string }) {
    const response = await fetchLike(request);
    this.store.set(request.url, response.body);
  }

  async put(request: { url: string }, response: FakeResponse) {
    this.store.set(request.url, response.body);
  }

  async match(request: string | { url: string }) {
    const url = typeof request === "string" ? request : request.url;
    const body = this.store.get(url);
    return body === undefined ? undefined : { ok: true, status: 200, url, type: "basic", body, clone: () => ({ ...responseOf(url, body) }) };
  }
}

function responseOf(url: string, body: string): FakeResponse {
  return { ok: true, status: 200, url, type: "basic", body, clone: () => responseOf(url, body) };
}

/** The exported site, as url -> body. A missing entry is a 404; networkUp=false is offline. */
const files = new Map<string, string>();
let networkUp = true;

function fetchLike(request: { url: string }): FakeResponse {
  if (!networkUp) throw new Error(`offline: ${request.url}`);
  // A static host serving an export with trailingSlash:false answers "/ride" with the
  // body of "/ride.html". The fake has to do the same or every navigation looks like a
  // 404 and the worker never reaches its network branch.
  // The worker precaches paths like "/index.html", not absolute URLs, so a base is
  // always supplied.
  const path = new URL(request.url, "http://localhost").pathname;
  const body = files.get(path) ?? files.get(`${path.replace(/\/+$/, "")}.html`) ?? files.get("/index.html");
  if (body === undefined) throw new Error(`404: ${request.url}`);
  return responseOf(request.url, body);
}

interface Handlers {
  install: ((event: unknown) => void) | null;
  activate: ((event: unknown) => void) | null;
  fetch: ((event: unknown) => void) | null;
  message: ((event: unknown) => void) | null;
}

function loadWorker(cacheNames: string[] = []): { handlers: Handlers; caches: Map<string, FakeCache> } {
  const handlers: Handlers = { install: null, activate: null, fetch: null, message: null };
  const caches = new Map<string, FakeCache>();
  const self = {
    addEventListener(type: keyof Handlers, handler: (event: unknown) => void) {
      handlers[type] = handler;
    },
    skipWaiting: async () => {},
    clients: { claim: async () => {} },
    location: { origin: "http://localhost" },
  };
  const environment = {
    self,
    caches: {
      async open(name: string) {
        if (!caches.has(name)) caches.set(name, new FakeCache());
        return caches.get(name) as FakeCache;
      },
      async keys() {
        // `cacheNames` stands in for caches left behind by an earlier build, which is
        // what activate() has to clean up.
        return [...caches.keys(), ...cacheNames];
      },
      async delete(name: string) {
        const existed = caches.has(name) || cacheNames.includes(name);
        caches.delete(name);
        return existed;
      },
    },
    fetch: async (request: { url: string }) => fetchLike(request),
    Request: class {
      url: string;
      constructor(url: string) {
        this.url = url;
      }
    },
    Response: class {
      status: number;
      constructor(_body: string, init?: { status?: number }) {
        this.status = init?.status ?? 200;
      }
    },
    URL: globalThis.URL,
    Promise,
    console,
  };
  const source = readFileSync(SW_PATH, "utf8");
  const keys = Object.keys(environment);
  new Function(...keys, source)(...keys.map((key) => (environment as Record<string, unknown>)[key]));
  return { handlers, caches };
}

/** Runs a handler and waits for whatever it queued with waitUntil. */
async function fire(handler: ((event: unknown) => void) | null, event: unknown) {
  assert.ok(handler, "the worker registered this handler");
  const waits: Promise<unknown>[] = [];
  handler({ ...(event as object), waitUntil: (promise: Promise<unknown>) => waits.push(promise) });
  await Promise.all(waits);
}

/** One fetch through the worker, resolved the way a page would see it. */
async function navigate(handlers: Handlers, path: string) {
  const requests: { respondWith: (r: unknown) => void }[] = [];
  const event = { request: { method: "GET", mode: "navigate", url: `http://localhost${path}` }, respondWith: () => {} };
  const holder = {
    request: event.request,
    respondWith(response: unknown) {
      requests.push({ respondWith: () => response });
    },
  };
  const handler = handlers.fetch;
  assert.ok(handler);
  handler(holder);
  assert.equal(requests.length, 1, "the worker answered the navigation");
  return await (requests[0] as unknown as { respondWith: () => Promise<unknown> }).respondWith();
}

const built = existsSync(SW_PATH);

// Skipped, not silently green, when the site has not been exported: the worker is a
// build artefact, and a test that quietly passes without it would be worse than none.
describe(
  "the generated service worker",
  { skip: built ? false : `${SW_PATH} is missing — run "npm run build" before the tests` },
  () => {
  it("precaches the exported site on install", async () => {
    files.clear();
    for (const url of ["/", "/index.html", "/ride.html", "/offline.html", "/manifest.webmanifest"]) {
      files.set(url, `<html>${url}</html>`);
    }
    const { handlers, caches } = loadWorker();
    await fire(handlers.install, {});
    const shell = caches.get([...caches.keys()][0]);
    assert.ok(shell, "the shell cache was opened");
    for (const url of ["/index.html", "/ride.html", "/offline.html"]) {
      const hit = await shell.match(url);
      assert.ok(hit, `${url} was precached`);
    }
  });

  it("serves /ride from the cache when the network is down", async () => {
    files.clear();
    files.set("/ride.html", "<html>ride page</html>");
    files.set("/offline.html", "<html>offline</html>");
    networkUp = true;
    const { handlers } = loadWorker();
    await fire(handlers.install, {});

    networkUp = false;
    const response = (await navigate(handlers, "/ride")) as { body?: string };
    assert.equal(response.body, "<html>ride page</html>", "/ride must resolve to the precached ride page");
  });

  it("serves /ride/ with a trailing slash from the same file", async () => {
    files.clear();
    files.set("/ride.html", "<html>ride page</html>");
    files.set("/offline.html", "<html>offline</html>");
    networkUp = true;
    const { handlers } = loadWorker();
    await fire(handlers.install, {});
    networkUp = false;
    const response = (await navigate(handlers, "/ride/")) as { body?: string };
    assert.equal(response.body, "<html>ride page</html>");
  });

  it("falls back to the offline page for something it has never seen", async () => {
    files.clear();
    files.set("/index.html", "<html>home</html>");
    files.set("/offline.html", "<html>offline</html>");
    networkUp = true;
    const { handlers } = loadWorker();
    await fire(handlers.install, {});
    networkUp = false;
    // /index.html is precached, so an unknown path lands on the home page rather than
    // the offline page. Both are correct; what matters is that it is not a dead end.
    const response = (await navigate(handlers, "/never-visited")) as { body?: string };
    assert.ok(response.body === "<html>home</html>" || response.body === "<html>offline</html>");
  });

  it("uses the network while it is up, so a new build is picked up", async () => {
    files.clear();
    files.set("/ride.html", "<html>cached ride</html>");
    networkUp = true;
    const { handlers } = loadWorker();
    await fire(handlers.install, {});
    files.set("/ride.html", "<html>fresh ride</html>");
    const response = (await navigate(handlers, "/ride")) as { body?: string };
    assert.equal(response.body, "<html>fresh ride</html>", "network first");
  });

  it("drops caches from an older build on activate", async () => {
    files.clear();
    files.set("/index.html", "<html>home</html>");
    const { handlers, caches } = loadWorker(["cholo-shell-oldversion", "cholo-runtime-oldversion"]);
    await fire(handlers.install, {});
    await fire(handlers.activate, {});
    const names = [...caches.keys()];
    assert.ok(!names.includes("cholo-shell-oldversion"), "the old shell cache is gone");
    assert.ok(!names.includes("cholo-runtime-oldversion"), "the old runtime cache is gone");
    assert.ok(names.length > 0 && names.every((name) => name.startsWith("cholo-")), "this build's caches remain");
  });

  it("leaves third-party requests alone", () => {
    const { handlers } = loadWorker();
    let responded = false;
    handlers.fetch?.({
      request: { method: "GET", url: "https://fonts.googleapis.com/css2?family=DM+Sans", mode: "cors" },
      respondWith: () => {
        responded = true;
      },
    });
    assert.equal(responded, false, "fonts are not cached, so they are not intercepted");
  });

  it("ignores non-GET requests", () => {
    const { handlers } = loadWorker();
    let responded = false;
    handlers.fetch?.({
      request: { method: "POST", url: "http://localhost/api", mode: "cors" },
      respondWith: () => {
        responded = true;
      },
    });
    assert.equal(responded, false, "a POST is never answered from a cache");
  });

  it("names its cache after a hash of the files, so versions cannot collide", () => {
    const source = readFileSync(SW_PATH, "utf8");
    const version = source.match(/const VERSION = "([0-9a-f]+)"/);
    assert.ok(version, "the worker carries a build version");
    assert.equal(version[1].length, 12, "a 12-character content hash");
    assert.ok(source.includes("cholo-shell-"), "and the cache name is derived from it");
  });
});
